/**
 * An icon as an SVG element, or null for an unknown name.
 *
 * @param {string} name   Name from bin/build-ui-icons.js.
 * @param {number} [size] Width and height in pixels.
 * @return {Element|null} SVG element.
 */
export function uiIcon( name, size = 24 ) {
	const icon = ICONS[ name ];
	if ( ! icon ) {
		return null;
	}
	const [ svgAttrs, children ] = icon;
	return createElement(
		'svg',
		{ xmlns: 'http://www.w3.org/2000/svg', width: size, height: size, 'aria-hidden': true, focusable: false, ...svgAttrs },
		...children.map( ( [ tag, childAttrs ], index ) => createElement( tag, { key: index, ...childAttrs } ) )
	);
}

/**
 * Icon for a field type, falling back to a plain block.
 *
 * @param {string} type   Field type name.
 * @param {number} [size] Width and height in pixels.
 * @return {Element} SVG element.
 */
export function typeIcon( type, size = 20 ) {
	return uiIcon( `type-${ type }`, size ) || uiIcon( 'type-default', size );
}

export function hasIcon( name ) {
	return Object.prototype.hasOwnProperty.call( ICONS, name );
}
